// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.alarmimport android.content.Contextimport androidx.work.CoroutineWorkerimport androidx.work.WorkerParametersimport timber.log.Timber/** * NOUS — Alarm Reschedule Worker (Module 13 v2 — audit P0 fix). * * Enqueued by [AlarmReceiver.handleBootCompleted] on device boot. * Reads all active alarms from the AlarmStore via [AlarmEngine.rescheduleAllAlarms] * and re-registers each with AlarmManager. * * ## Why a Worker (not direct call in onReceive)? * * `BroadcastReceiver.onReceive` has a 10-second ANR window. Reading from Room * + scheduling N alarms via AlarmManager can exceed this on slow devices or * when many alarms are stored. WorkManager runs on a background thread. * * ## Bridge pattern * * Workers can't use Hilt constructor injection (instantiated via reflection by * WorkManager). [AlarmEngineBridge] is a static singleton set by * [com.roshan.persona.productivity.di.ProductivityModule] at app startup — * same pattern as `SosLocationWorkerBridge` in Module 11. * * @see AlarmReceiver * @see AlarmEngine.rescheduleAllAlarms */class AlarmRescheduleWorker(    appContext: Context,    params: WorkerParameters,) : CoroutineWorker(appContext, params) {    override suspend fun doWork(): Result {        val engine = AlarmEngineBridge.alarmEngine        if (engine == null) {            Timber.tag(TAG).w("AlarmEngine not available — retrying.")            return Result.retry()        }        return try {            engine.rescheduleAllAlarms()            Timber.tag(TAG).i("Alarm reschedule complete.")            Result.success()        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Alarm reschedule failed — retrying.")            Result.retry()        }    }    companion object {        private const val TAG = "AlarmRescheduleWorker"        const val UNIQUE_WORK_NAME = "nous_alarm_reschedule"    }}/** * Static bridge for [AlarmRescheduleWorker] to access the Hilt-provided * [AlarmEngine]. Set by [com.roshan.persona.productivity.di.ProductivityModule] * at app startup. */object AlarmEngineBridge {    @Volatile    var alarmEngine: AlarmEngine? = null}
